const b = $json.body || {};
const emoji = ({
  'service.alert': '🚨', 'auto_fix.completed': '✅', 'auto_fix.failed': '❌',
  'auto_fix.skipped': '⏭️', 'incident.ticket_created': '🎫',
  'system.deadletter': '💀', 'system.workflow_failed': '🛠️',
  'task.completed': '✔️', 'document.indexed': '📄'
})[b.event_type] || '🔔';
const lines = [
  `${emoji} DailyOps — ${b.event_type}`,
  `source: ${b.source}`,
  b.severity ? `severity: ${b.severity}` : null,
  b.service ? `service: ${b.service}` : null,
  `event_id: ${b.event_id}`,
  b.payload && Object.keys(b.payload).length ? JSON.stringify(b.payload) : null,
].filter(Boolean);
const item = {
  event_id: b.event_id,
  event_type: b.event_type,
  severity: b.severity || 'unknown',
  channel: b.severity === 'critical' ? 'telegram' : 'log',
  message: lines.join('\n'),
  started_at: new Date().toISOString(),
};
item.response = { accepted: true, event_id: item.event_id, execution_id: $execution.id, workflow: 'notify' };
return [{ json: item }];

const i = $('Init & Format Message').item.json;
return [{ json: { publish: {
  event_id: 'evt_' + $execution.id + '-result',
  event_type: 'notify.completed',
  source: 'n8n.notify',
  timestamp: new Date().toISOString(),
  correlation_id: i.event_id,
  correlation_workflow: 'notify',
  severity: i.severity,
  payload: { channel: i.channel, started_at: i.started_at }
} } }];
